SELECT /*selectMasterMpRqReqNegoReceiptList*/ Z.BUYER, /* 1 */ Z.BUYER_NAME, /* 2 */ Z.QUOTATION_NO, /* 3 */ Z.QUOTATION_SEQ, /* 4 */ Z.REVISION, /* 5 */ Z.DESCRIPTION, /* 6 */ Z.ORIGIN_NAME, /* 7 */ Z.UNIT_MEASURE, /* 8 */ Z.ITEM_QTY, /* 9 */ Z.BTOA_NEGO_PRICE, /* 10 */ Z.KEP_USER_ID, /* 11 */ Z.KEP_USER_NAME, /* 12 */ Z.BUYER_ITEM_NO, /* 13 */ Z.NEGO_STATUS, /* 14 */ Z.SPECIFICATION, /* 15 */ Z.MAKER_NAME, /* 16 */ Z.STOA_LIST_PRICE, /* 17 */ Z.AGENT, /* 19 */ Z.AGENT_NAME, /* 20 */ Z.REG_ITEM_NO, /* 21 */ TO_CHAR(TO_DATE(Z.BTOA_END_DATE,'YYYYMMDD'),'YYYY/MM/DD') || ' ' || SUBSTR(Z.BTOA_END_TIME,1,2) || ':'|| SUBSTR(Z.BTOA_END_TIME,3,2) AS BTOA_END_DT, TO_CHAR(TO_DATE(Z.ATOS_END_DATE,'YYYYMMDD'),'YYYY/MM/DD') || ' ' || SUBSTR(Z.ATOS_END_TIME,1,2) || ':'|| SUBSTR(Z.ATOS_END_TIME,3,2) AS ATOS_END_DT, Z.BTOA_USER_NAME, /* 26 */ Z.BTOA_USER_ID, /* 27 */ Z.CONTRACT_NO, /* 28 */ Z.CONTRACT_SEQ, /* 29 */ Z.BYCA_COMORG_CODE, /* 30 */ Z.PASS_FLAG, /* 31 */ Z.CANCEL_REMARK, /* 33 */ '0' AS CANCEL_REMARK_IMG, Z.BTOA_REMARK, Z.ATOB_REMARK, /* 34 */ DECODE(Z.ATOB_REMARK,'',0,1) AS ATOB_REMARK_IMG, Z.ATOS_REMARK, DECODE(Z.REJECT_REMARK,'',0,1) AS ATOS_REMARK_IMG, Z.STOA_REMARK, Z.RATE_FLAG, /* 35 */ Z.BUYER_RATE, /* 36 */ Z.SG_ID, /* 37 */ Z.MAKER_CODE, /* 38 */ Z.SG_NAME, /* 39 */ Z.AG_ID, /* 40 */ Z.AG_SI, /* 41 */ Z.BUYER_TARGET_PRICE, /* 42 */ Z.ADMIN_TARGET_PRICE, /* 43 */ Z.AGENT_CNT, /* 44 */ Z.AGENT_LIST /* 45 */ , Z.OPM_FLAG , Z.REJECT_REMARK , Z.BELOW_COMORG_CODE AS INIT_BELOW_COMORG_CODE , Z.SG_KEP_YN , Z.SG_GBN , Z.KEP_RFQ_FLAG , Z.KEP_RFQ_FLAG AS KEP_RFQ_ORJ_FLAG , Z.BUYER_MNG_YN , Z.REQ_PRICE_TYPE , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M150' AND CODE = Z.REQ_PRICE_TYPE AND FLAG = 'Y') AS REQ_PRICE_TYPE_TEXT , DECODE(Z.ATOA_REMARK,'',0,1) AS ATOA_REMARK_IMG , Z.ATOA_REMARK , Z.QTDT_ATOB_UNIT_PRICE , Z.JOB_TRANSFER_NM , Z.JOB_TRANSFER_ID , Z.JOB_TRANSFER_DATE , Z.DELAY_REASON_IMG , Z.DELAY_REASON_CODE , Z.DELAY_SEND_MAIL_FLAG , Z.PLANT_USER_NM , DECODE((SELECT COUNT(CODE) FROM ICOMCOD1 COD WHERE COD.TYPE = 'EXCCMPY' AND COD.FLAG = 'Y' AND COD.CODE = Z.BUYER), 0, 999999, (SELECT TEXT1 FROM ICOMCOD3 A WHERE A.BUYER = 'KRKORE0001' AND A.TYPE = 'CMSG' AND A.CODE1 = Z.BUYER AND A.CODE2 = Z.SG_ID AND A.FLAG = 'Y')) AS CMPY_QTT_RATE , (SELECT DECODE(COUNT(A.SLG_ID), 0, 'N', 'Y') FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = Z.BUYER AND A.SLG_ID = 'P04-4041-09') AS UNIT_PRICE_CHECK_FLAG , (SELECT DECODE(COUNT(A.SLG_ID), 0, 0, MAX(B.COL01_DATA)) FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = Z.BUYER AND A.SLG_ID = 'P04-4041-09') AS MIN_UNIT_PRICE , (SELECT DECODE(COUNT(A.SLG_ID), 0, 9999999999, MAX(B.COL02_DATA)) FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = Z.BUYER AND A.SLG_ID = 'P04-4041-09') AS MAX_UNIT_PRICE , Z.NEGO_CMS_REJECT_YN , Z.NEGO_ITEM_CHG_REQ_NM , Z.NEGO_ITEM_CHG_REQ_DATE , Z.NEGO_ITEM_CHG_REQ_NOTE , Z.NEGO_ITEM_CHG_REQ_IMAGE_KEY , Z.NEGO_ITEM_CHG_REQ_IMAGE_KEY_IMG , Z.NEGO_ITEM_MD_USER_NM , Z.NEGO_ITEM_MD_DATE , Z.NEGO_ITEM_MD_REVISION , Z.NEGO_ITEM_CHG_REQ_ID , DECODE(Z.NOTE_MNG, 0, 0, 1) AS NOTE_MNG_IMG , DECODE(NVL(Z.PRE_GR_FLAG,'Y'),'Y','1','0') AS PRE_GR_FLAG , Z.IMAGE_KEY , Z.IMAGE_KEY_IMG , Z.SELLER_IMAGE_KEY , Z.SELLER_IMAGE_KEY_IMG , Z.MSDS_YN , Z.MSDS_NO , Z.CMC_REQ_DATE , Z.CMC_REQ_NO , Z.CMC_REQ_STATUS , Z.NEGO_ITEM_MD_COMPLETE , Z.NEGO_ITEM_CHG_REQ_TYPE , CASE WHEN TO_CHAR(TO_DATE(Z.BTOA_DATE, 'YYYYMMDD') + 5, 'YYYYMMDD') > Z.BTOA_END_DATE THEN CASE WHEN TO_CHAR(SYSDATE, 'YYYYMMDD') > TO_CHAR(TO_DATE(Z.BTOA_DATE, 'YYYYMMDD') + 5, 'YYYYMMDD') THEN 'Y' ELSE 'N' END ELSE CASE WHEN TO_CHAR(SYSDATE, 'YYYYMMDD') > Z.BTOA_END_DATE THEN 'Y' ELSE 'N' END END AS DELAY_FLAG FROM ( SELECT ROWNUM NUM, Y.BUYER, Y.BUYER_NAME, Y.QUOTATION_NO, Y.QUOTATION_SEQ, Y.REVISION, Y.DESCRIPTION, Y.ORIGIN_NAME, Y.UNIT_MEASURE, Y.ITEM_QTY, Y.BTOA_NEGO_PRICE, Y.KEP_USER_ID, Y.KEP_USER_NAME, Y.BUYER_ITEM_NO, Y.NEGO_STATUS, Y.SPECIFICATION, Y.MAKER_NAME, Y.STOA_LIST_PRICE, Y.AGENT, Y.AGENT_NAME, Y.REG_ITEM_NO, Y.BTOA_DATE, Y.BTOA_END_DATE, Y.BTOA_END_TIME, Y.ATOS_END_DATE, Y.ATOS_END_TIME, Y.BTOA_USER_NAME, Y.BTOA_USER_TEL, Y.BTOA_USER_ID, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYCA_COMORG_CODE, Y.PASS_FLAG, Y.CANCEL_REMARK, Y.BTOA_REMARK, Y.ATOS_REMARK, Y.STOA_REMARK, Y.ATOB_REMARK, Y.RATE_FLAG, Y.BUYER_RATE, Y.SG_ID, Y.MAKER_CODE, Y.SG_NAME, Y.AG_ID, Y.AG_SI, Y.BUYER_TARGET_PRICE, Y.ADMIN_TARGET_PRICE, Y.AGENT_CNT, Y.AGENT_LIST , Y.OPM_FLAG , Y.REJECT_REMARK , Y.BELOW_COMORG_CODE , Y.SG_KEP_YN , Y.SG_GBN , Y.KEP_RFQ_FLAG , Y.BUYER_MNG_YN , Y.REQ_PRICE_TYPE , Y.ATOA_REMARK , Y.QTDT_ATOB_UNIT_PRICE , Y.JOB_TRANSFER_NM , Y.JOB_TRANSFER_ID , Y.JOB_TRANSFER_DATE , Y.DELAY_REASON_IMG , Y.DELAY_REASON_CODE , Y.DELAY_SEND_MAIL_FLAG , Y.PLANT_USER_NM , Y.NEGO_CMS_REJECT_YN , Y.NEGO_ITEM_CHG_REQ_NM , Y.NEGO_ITEM_CHG_REQ_DATE , Y.NEGO_ITEM_CHG_REQ_NOTE , Y.NEGO_ITEM_CHG_REQ_IMAGE_KEY , Y.NEGO_ITEM_CHG_REQ_IMAGE_KEY_IMG , Y.NEGO_ITEM_MD_USER_NM , Y.NEGO_ITEM_MD_DATE , Y.NEGO_ITEM_MD_REVISION , Y.NEGO_ITEM_CHG_REQ_ID , Y.BTOA_USER_TEL , Y.NOTE_MNG , Y.PRE_GR_FLAG , Y.IMAGE_KEY , Y.IMAGE_KEY_IMG , Y.SELLER_IMAGE_KEY , Y.SELLER_IMAGE_KEY_IMG , Y.MSDS_YN , Y.MSDS_NO , Y.CMC_REQ_DATE , Y.CMC_REQ_NO , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CM01' AND COD.CODE = Y.CMC_REQ_STATUS) AS CMC_REQ_STATUS , Y.NEGO_ITEM_MD_COMPLETE , Y.NEGO_ITEM_CHG_REQ_TYPE FROM ( SELECT X.BUYER, X.BUYER_NAME, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION, X.DESCRIPTION, X.ORIGIN_NAME, X.UNIT_MEASURE, X.ITEM_QTY, X.BTOA_NEGO_PRICE, X.KEP_USER_ID, X.KEP_USER_NAME, X.BUYER_ITEM_NO, X.NEGO_STATUS, X.SPECIFICATION, X.MAKER_NAME, X.STOA_LIST_PRICE, X.AGENT, X.AGENT_NAME, X.REG_ITEM_NO, X.BTOA_DATE, X.BTOA_END_DATE, X.BTOA_END_TIME, X.ATOS_END_DATE, X.ATOS_END_TIME, X.BTOA_USER_NAME, X.BTOA_USER_TEL, X.BTOA_USER_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYCA_COMORG_CODE, X.PASS_FLAG, X.CANCEL_REMARK, X.BTOA_REMARK, X.ATOS_REMARK, X.STOA_REMARK, X.ATOB_REMARK, DECODE(X.BUYER_RATE_GAIN, 0, 'N','Y') AS RATE_FLAG, X.BUYER_RATE, X.SG_ID, X.MAKER_CODE, X.SG_NAME, X.AG_ID, X.AG_SI, X.BUYER_TARGET_PRICE, X.ADMIN_TARGET_PRICE, X.AGENT_CNT, X.AGENT_LIST , X.OPM_FLAG , X.REJECT_REMARK , X.BELOW_COMORG_CODE , X.SG_KEP_YN , X.SG_GBN , X.KEP_RFQ_FLAG , X.BUYER_MNG_YN , X.REQ_PRICE_TYPE , X.ATOA_REMARK , X.QTDT_ATOB_UNIT_PRICE , X.JOB_TRANSFER_NM , X.JOB_TRANSFER_ID , X.JOB_TRANSFER_DATE , X.DELAY_REASON_IMG , X.DELAY_REASON_CODE , X.DELAY_SEND_MAIL_FLAG , X.PLANT_USER_NM , X.NEGO_CMS_REJECT_YN , X.NEGO_ITEM_CHG_REQ_NM , X.NEGO_ITEM_CHG_REQ_DATE , X.NEGO_ITEM_CHG_REQ_NOTE , X.NEGO_ITEM_CHG_REQ_IMAGE_KEY , X.NEGO_ITEM_CHG_REQ_IMAGE_KEY_IMG , X.NEGO_ITEM_MD_USER_NM , X.NEGO_ITEM_MD_DATE , X.NEGO_ITEM_MD_REVISION , X.NEGO_ITEM_CHG_REQ_ID , X.NOTE_MNG , X.PRE_GR_FLAG , X.IMAGE_KEY , X.IMAGE_KEY_IMG , X.SELLER_IMAGE_KEY , X.SELLER_IMAGE_KEY_IMG , X.MSDS_YN , X.MSDS_NO , (SELECT TO_CHAR(REQ_DATE, 'YYYY/MM/DD HH24:MI') FROM KEP_CMC_REQ WHERE REQ_NO = X.CMC_REQ_NO) AS CMC_REQ_DATE , X.CMC_REQ_NO , (SELECT REQ_STATUS FROM KEP_CMC_REQ WHERE REQ_NO = X.CMC_REQ_NO) AS CMC_REQ_STATUS , X.NEGO_ITEM_MD_COMPLETE , X.NEGO_ITEM_CHG_REQ_TYPE FROM( SELECT A.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') AS BUYER_NAME, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, A.DESCRIPTION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=A.ORIGIN_NAME) AS ORIGIN_NAME, A.UNIT_MEASURE, A.ITEM_QTY, A.BTOA_NEGO_PRICE, A.KEP_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.KEP_USER_ID AND STATUS <> 'D') KEP_USER_NAME, A.BUYER_ITEM_NO, DECODE(A.ATOB_UNIT_PRICE, 0, 'Nego요청','Nego제출') AS NEGO_STATUS, A.SPECIFICATION, A.MAKER_NAME, B.STOA_LIST_PRICE, B.AGENT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=B.AGENT AND STATUS <> 'D') AGENT_NAME, A.REG_ITEM_NO, A.BTOA_DATE, A.BTOA_END_DATE, A.BTOA_END_TIME, B.ATOS_END_DATE, B.ATOS_END_TIME, A.BTOA_USER_NAME, A.BTOA_USER_TEL, A.BTOA_USER_ID, A.CONTRACT_NO, A.CONTRACT_SEQ, (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D') BYCA_COMORG_CODE, NVL(A.PASS_FLAG,'N') PASS_FLAG, A.CANCEL_REMARK, NVL(A.BTOA_REMARK,'') BTOA_REMARK, NVL(A.ATOS_REMARK,'') ATOS_REMARK, NVL((SELECT B.STOA_REMARK FROM KEPQTDT B WHERE A.BUYER=B.BUYER AND A.QUOTATION_NO=B.QUOTATION_NO AND A.QUOTATION_SEQ=B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND B.STATUS IN ('C','R') AND B.BID_SUCCESS_FLAG='Y'),'') STOA_REMARK, NVL(A.ATOB_REMARK,'') ATOB_REMARK, (SELECT COUNT(*) FROM KEPQTDT QTDT WHERE QTDT.BUYER = B.BUYER AND QTDT.QUOTATION_NO = B.QUOTATION_NO AND QTDT.QUOTATION_SEQ= B.QUOTATION_SEQ AND QTDT.REVISION = B.REVISION AND QTDT.STATUS IN ('C','R') AND NVL(QTDT.STOA_LIST_PRICE,0) ^= 0 AND NVL(QTDT.ATOB_UNIT_PRICE,0) ^= 0 AND QTDT.BID_SUCCESS_FLAG = 'Y' AND EXISTS (SELECT 'X' FROM MIS_MNG_BUYER_RATE C WHERE TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN C.FROM_DATE AND C.TO_DATE AND C.BUYER = QTDT.BUYER AND C.BUYER_RATE*.9 >= (1-QTDT.STOA_LIST_PRICE/QTDT.ATOB_UNIT_PRICE)*100)) AS BUYER_RATE_GAIN, (SELECT NVL(BUYER_RATE,0) FROM MIS_MNG_BUYER_RATE WHERE BUYER =A.BUYER)AS BUYER_RATE, (SELECT SG_ID FROM CMSCATEG WHERE CMS_CATEG_ID = A.CMS_CATEG_ID) AS SG_ID, A.MAKER_CODE AS MAKER_CODE, (SELECT SG_NAME FROM KEPSGMG WHERE SG_ID = (SELECT SG_ID FROM CMSCATEG WHERE CMS_CATEG_ID = A.CMS_CATEG_ID)) AS SG_NAME, (SELECT AG_ID FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS AG_ID, (SELECT MAX(SIDO) FROM ICOMZIPC WHERE AG_ID = (SELECT AG_ID FROM ICOMCMPY WHERE COM_CODE = A.BUYER)) AS AG_SI, A.BUYER_TARGET_PRICE, A.ADMIN_TARGET_PRICE, (SELECT COUNT(*) FROM KEPQTDT WHERE BUYER = B.BUYER AND QUOTATION_NO = B.QUOTATION_NO AND QUOTATION_SEQ = B.QUOTATION_SEQ AND REVISION = B.REVISION AND AGENT_REVISION = B.AGENT_REVISION AND STATUS = 'C') AS AGENT_CNT, F_AGENT_LIST(B.BUYER, B.QUOTATION_NO, B.QUOTATION_SEQ, B.REVISION, B.AGENT_REVISION) AS AGENT_LIST , CASE WHEN A.BUYER = 'KRKOLO0001' THEN 'PM' /* 코오롱인더스트리(주)구미공장 */ WHEN A.BUYER = 'KRKOLO0002' THEN 'PM' /* 코오롱인더스트리(주)경산공장 */ WHEN A.BUYER = 'KRKOLO0003' THEN 'PM' /* 코오롱인더스트리(주)김천공장 */ WHEN A.BUYER = 'KRDOOD0001' THEN 'PM' /* 두산중공업(주) */ WHEN NVL(B.ITEM_QTY,0)* NVL(B.STOA_LIST_PRICE,0) >= 500000 THEN 'PM' WHEN A.PRE_GR_FLAG = 'Y' THEN 'PM' WHEN B.BID_SUCCESS_CODE != 'BS01' THEN 'PM' WHEN (SELECT COUNT(*) FROM KEPQTDT WHERE BUYER = B.BUYER AND QUOTATION_NO = B.QUOTATION_NO AND QUOTATION_SEQ = B.QUOTATION_SEQ AND REVISION = B.REVISION AND AGENT_REVISION = B.AGENT_REVISION AND STATUS = 'C' AND NVL(STOA_LIST_PRICE,0) > 0 AND STOA_DATE IS NOT NULL ) <= 1 THEN 'PM' ELSE 'NO' END AS OPM_FLAG /* , DECODE(A.BUYER, 'KRDOOD0001', DECODE(A.PASS_FLAG, 'Y', 'PM', (SELECT CASE WHEN SUM(ITEM_QTY * STOA_LIST_PRICE)>=500000 THEN 'PM' ELSE 'NO' END PM_FLAG FROM KEPQTDT WHERE BUYER=B.BUYER AND QUOTATION_NO=B.QUOTATION_NO AND REVISION=B.REVISION AND BID_SUCCESS_FLAG='Y' AND STATUS IN ('C','R') GROUP BY BUYER, QUOTATION_NO, REVISION)), (CASE WHEN NVL(B.ITEM_QTY,0)* NVL(B.STOA_LIST_PRICE,0) >= 500000 THEN 'PM' ELSE 'NO' END)) AS OPM_FLAG */ , A.REJECT_REMARK , A.BELOW_COMORG_CODE ,F_GET_RE_SGMNG(A.BUYER, A.CMS_CATEG_ID,#{USR_ID},1) AS SG_KEP_YN ,F_GET_RE_SGMNG(A.BUYER, A.CMS_CATEG_ID,#{USR_ID},0) AS SG_GBN , DECODE(NVL( A.KEP_RFQ_FLAG,'Y'),'Y','1','0') AS KEP_RFQ_FLAG , DECODE((SELECT COUNT(KEP_USER_ID) FROM MIS_BUYER_MNG MNG WHERE MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS != 'D' AND MNG.BUYER = A.BUYER AND MNG.KEP_USER_ID = #{USR_ID}),0,'N','Y') BUYER_MNG_YN , A.REQ_PRICE_TYPE , A.ATOA_REMARK , B.ATOB_UNIT_PRICE AS QTDT_ATOB_UNIT_PRICE , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =A.JOB_TRANSFER_ID) AS JOB_TRANSFER_NM ,A.JOB_TRANSFER_ID ,TO_CHAR(A.JOB_TRANSFER_DATE,'YYYY/MM/DD HH24:MI') AS JOB_TRANSFER_DATE ,DECODE(A.DELAY_REASON_CODE,'','8','9') AS DELAY_REASON_IMG ,A.DELAY_REASON_CODE ,A.DELAY_SEND_MAIL_FLAG , F_GET_PLANT_MNG(A.BUYER ,A.PLANT ,'REMG' ,'NM') AS PLANT_USER_NM , A.SELL_CLOSE_DATE , A.BUY_CLOSE_DATE , (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_CMS_REJECT_YN , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT ITEM_MD_REQ_USER_ID FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C')) AS NEGO_ITEM_CHG_REQ_NM , (SELECT TO_CHAR(ITEM_MD_REQ_DATE, 'YYYY/MM/DD HH24:MI') FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_DATE , (SELECT ITEM_MD_REQ_NOTE FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_NOTE , (SELECT ITEM_MD_REQ_IMAGE_KEY FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_IMAGE_KEY , (SELECT DECODE(COUNT(ITEM_MD_REQ_IMAGE_KEY),0,2,3) FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_IMAGE_KEY_IMG , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT ITEM_MD_USER_ID FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C')) AS NEGO_ITEM_MD_USER_NM , (SELECT TO_CHAR(ITEM_MD_DATE, 'YYYY/MM/DD HH24:MI') FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_MD_DATE , (SELECT ITEM_MD_REVISION FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_MD_REVISION , (SELECT ITEM_MD_REQ_USER_ID FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_ID , (SELECT COUNT(MNG.ADD_NOTE) FROM KEP_RQDT_NOTE_MNG MNG WHERE MNG.BUYER = A.BUYER AND MNG.QUOTATION_NO = A.QUOTATION_NO AND MNG.QUOTATION_SEQ = A.QUOTATION_SEQ AND MNG.REVISION = A.REVISION AND MNG.STATUS != 'D') AS NOTE_MNG , A.PRE_GR_FLAG , A.IMAGE_KEY , DECODE(A.IMAGE_KEY,'',2,3) AS IMAGE_KEY_IMG , A.SELLER_IMAGE_KEY , DECODE(A.SELLER_IMAGE_KEY,'',2,3) AS SELLER_IMAGE_KEY_IMG , DECODE(A.MSDS_YN, 'Y', '1', '0') AS MSDS_YN , A.MSDS_NO , (SELECT MAX(REQ_NO) FROM KEP_CMC_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND REQ_STATUS NOT IN ('D', 'N')) AS CMC_REQ_NO , (SELECT DECODE(COUNT(*), 0, 'Y', 'N') FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C' AND ITEM_MD_USER_ID IS NULL) AS NEGO_ITEM_MD_COMPLETE , (SELECT ITEM_MD_REQ_TYPE FROM KEP_NEGO_ITEM_MD_REQ REQ WHERE REQ.BUYER = A.BUYER AND REQ.QUOTATION_NO = A.QUOTATION_NO AND REQ.QUOTATION_SEQ = A.QUOTATION_SEQ AND REQ.REVISION = A.REVISION AND REQ.ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_TYPE FROM KEPRQDT A LEFT OUTER JOIN KEPQTDT B ON (1 = 1 AND B.BUYER = A.BUYER AND B.QUOTATION_NO = A.QUOTATION_NO AND B.QUOTATION_SEQ = A.QUOTATION_SEQ AND B.REVISION = A.REVISION AND B.BID_SUCCESS_FLAG = 'Y' AND B.STATUS = 'C' ) WHERE 1 = 1 AND A.RECV_FLAG NOT IN ('GD','PM') AND A.ATOB_UNIT_PRICE=0 AND A.BTOA_NEGO_PRICE <> 0 AND A.ATOB_SEND_FLAG='Y'
AND A.BUYER IN
#{item}
AND A.KEP_USER_ID=#{st_kep_user_id}
AND A.QUOTATION_NO LIKE '%' || #{st_quotation_no} || '%'
AND A.DESCRIPTION LIKE '%' || #{st_description} || '%'
AND A.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND A.JOB_TRANSFER_ID = #{st_job_transfer_id}
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND NOT EXISTS ( SELECT 1 FROM ICOMCOD1 COD WHERE COD.TYPE ='EXCCMPY' AND COD.CODE = A.BUYER AND COD.FLAG = 'Y' ) AND A.SG_ID IN ( SELECT CODE1 FROM ICOMCOD3 COD WHERE COD.BUYER ='KRKORE0001' AND COD.TYPE ='CMDSM' AND COD.TEXT1 = #{st_user_id} AND COD.FLAG ='Y' UNION SELECT CODE1 FROM ICOMCOD3 COD WHERE COD.BUYER ='KRKORE0001' AND COD.TYPE ='CMSM' AND COD.TEXT1 = #{st_user_id} AND COD.FLAG ='Y' UNION SELECT CODE1 FROM ICOMCOD3 A, ICOMLUSR B WHERE A.BUYER ='KRKORE0001' AND A.TYPE ='CMDSM' AND A.TEXT1 = B.USER_ID AND B.DEPARTMENT IN (SELECT DECODE(C.USER_TYPE,'ST',C.DEPARTMENT,'SOF',B.DEPARTMENT,'') FROM ICOMLUSR C WHERE C.USER_ID =#{st_user_id}) )
AND DECODE((SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM ICOMCOD1 WHERE TYPE = 'EXCCMPY' AND CODE = A.BUYER), 'Y', 'N', (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM ICOMCOD3 WHERE TYPE = 'CMDSM' AND FLAG = 'Y' AND CODE1 = A.SG_ID)) = 'N'
AND A.CMS_CATEG_ID IN ( SELECT COD.CODE2 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'SG' AND CODE1 = #{st_sg_user_id} AND FLAG = 'Y' ) AND NOT EXISTS (
SELECT 1 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'SGC' AND COD.CODE1 = A.BUYER AND COD.CODE2 = 'ALL' UNION ALL SELECT 1 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'SGC' AND COD.CODE1 = A.BUYER AND COD.CODE2 = A.CMS_CATEG_ID
)
AND ((A.BUYER, NVL(A.PLANT,'NULL_')) IN ( SELECT COD.TEXT1,COD.TEXT2 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'REMG' AND COD.CODE1 = #{st_plant_user_id} AND COD.FLAG = 'Y' ) OR 0 = (SELECT COUNT(*) FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'REMG' AND COD.TEXT2 = A.PLANT AND COD.FLAG = 'Y') )
AND (A.BUYER, NVL(A.PLANT,'NULL_')) IN ( SELECT COD.TEXT1,COD.TEXT2 FROM ICOMCOD3 COD WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'REMG' AND COD.CODE1 = #{st_plant_user_id} AND COD.FLAG = 'Y' )
) X WHERE 1=1
AND NVL(X.NEGO_CMS_REJECT_YN, 'N') = #{st_nego_cms_reject_yn}
AND (NVL(TRIM(X.NEGO_CMS_REJECT_YN), 'N') = 'N' OR (X.NEGO_CMS_REJECT_YN = 'Y' AND X.NEGO_ITEM_MD_USER_NM IS NOT NULL))
AND X.NEGO_CMS_REJECT_YN = 'Y' AND (X.NEGO_ITEM_MD_USER_NM IS NULL OR X.NEGO_ITEM_MD_USER_NM = '')
) Y ) Z


SELECT/*getMaxAgentRevision*/							
		NVL(MAX(AGENT_REVISION)+1,0) AS AGENT_REVISION
		, NVL(MAX(AGENT_REVISION)+1,0) -1 AS PRE_AGENT_REVISION
   FROM KEPQTDT						
  WHERE BUYER=#{BUYER}						
	AND QUOTATION_NO=#{QUOTATION_NO}				
	AND QUOTATION_SEQ=#{QUOTATION_SEQ}				
	AND REVISION=#{REVISION}					
	AND STATUS IN ('C','R','O')

