UPDATE KEP_NEGO_ITEM_MD_REQ 
   SET ITEM_MD_STATUS = 'O'
 WHERE BUYER = #{BUYER}  
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION} 
   AND ITEM_MD_REVISION = #{NEGO_ITEM_MD_REVISION}


UPDATE KEP_NEGO_ITEM_MD_REQ /*updateMasterMpRqNegoItmMdSend1*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND ITEM_MD_REVISION = #{NEGO_ITEM_MD_REVISION}
   AND ITEM_MD_STATUS = 'C'


/*updateMasterMpRqNegoItmMdSend2*/
UPDATE	KEPRQDT
SET		DELETE_SCHD_DATE = NULL
WHERE	1=1
AND		BUYER = #{BUYER}
AND		QUOTATION_NO = #{QUOTATION_NO}
AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
AND		REVISION = #{REVISION}


UPDATE	KEPRQDT /*updateMasterMpRqNegoInfoKEPRQDT*/               
SET		ATOB_REMARK=#{ATOB_REMARK},
		PRE_GR_FLAG = DECODE(#{PRE_GR_FLAG},'1','Y','N'),
		SELLER_IMAGE_KEY = #{SELLER_IMAGE_KEY},
		IMAGE_KEY = #{IMAGE_KEY}
WHERE	BUYER=#{BUYER}
AND		QUOTATION_NO=#{QUOTATION_NO}
AND		QUOTATION_SEQ=#{QUOTATION_SEQ}
AND		REVISION=#{REVISION}
AND		STATUS <> 'D'
